<div class="modal fade" id="featuresModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><form method="post"><div class="modal-header"><div><h2 class="modal-title fs-5">Portal features</h2><div class="small text-body-secondary" id="feature-station-name"></div></div><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="save_station_features"><input type="hidden" name="id" value="0"><p class="small text-body-secondary">Each feature can inherit the router default or be overridden for this station.</p><div class="row g-3"><?php foreach($featureLabels as $key=>$label):?><div class="col-md-6"><label><?= e($label) ?></label><select name="<?= e($key) ?>" data-feature="<?= e($key) ?>"><option value="inherit">Inherit router</option><option value="on">Enabled</option><option value="off">Disabled</option></select></div><?php endforeach;?><div class="col-md-4"><label>Trial minutes</label><input type="number" name="trial_minutes" min="1" max="1440" value="10"></div><div class="col-md-4"><label>Convert points</label><input type="number" name="convert_points" min="1" value="10"></div><div class="col-md-4"><label>Convert to minutes</label><input type="number" name="convert_minutes" min="1" value="5"></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="button" type="submit">Save overrides</button></div></form></div></div></div>

<div class="modal fade" id="stationModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><form method="post"><div class="modal-header"><h2 class="modal-title fs-5" id="stationModalTitle">Add hotspot station</h2><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="create"><input type="hidden" name="id" value="0"><div class="row g-3"><div class="col-md-6"><label>Name / Wi-Fi name</label><input name="name" required maxlength="160"></div><div class="col-md-6"><label>Router</label><select name="router_id" required><?php foreach($routers as $r):?><option value="<?= e($r['id']) ?>"><?= e($r['name']) ?> · <?= e($r['identity']) ?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Portal theme</label><select name="portal_theme_id"><option value="0">Inherit router theme</option><?php foreach($themes as $theme):?><option value="<?= e($theme['id']) ?>"><?= e($theme['name']) ?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Server IP</label><input name="server_ip" required placeholder="10.0.3.1"></div><div class="col-md-6"><label>Client subnet</label><input name="client_subnet" placeholder="10.0.3.0/24"></div><div class="col-md-6"><label>Interface</label><input name="interface_name" placeholder="bridge-HS"></div><div class="col-md-6"><label>Password mode</label><select name="password_mode"><option value="blank">Blank password</option><option value="voucher">Voucher as password</option></select></div><div class="col-12"><div class="border rounded p-3"><div class="fw-semibold mb-2">Optional Vendo hardware</div><label>Controller address</label><input name="base_url" placeholder="Leave blank for no Vendo controller"><small class="text-body-secondary d-block">Required only when using the coin-slot feature.</small><div class="d-flex flex-wrap gap-4 mt-3 station-switches"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="charging_enabled" value="1" id="station-charging"><label class="form-check-label" for="station-charging">Phone charging</label></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="eload_enabled" value="1" id="station-eload"><label class="form-check-label" for="station-eload">E-load</label></div></div></div></div><div class="col-12 station-switches"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="enabled" value="1" id="station-enabled" checked><label class="form-check-label" for="station-enabled">Enabled</label></div></div></div></div><div class="modal-footer"><a class="btn btn-outline-info me-auto" href="/admin/portal-emulator">Open emulator</a><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="button" type="submit" id="station-submit">Add station</button></div></form></div></div></div>
<script>
const fm=document.getElementById('featuresModal');fm.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget,f=fm.querySelector('form'),data=JSON.parse(b.dataset.features||'{}');f.querySelector('[name=id]').value=b.dataset.id;document.getElementById('feature-station-name').textContent=b.dataset.name;f.querySelectorAll('[data-feature]').forEach(s=>{const v=data[s.dataset.feature]?.value;s.value=v===true?'on':v===false?'off':'inherit';});f.querySelector('[name=trial_minutes]').value=data.trial?.config?.minutes||10;f.querySelector('[name=convert_points]').value=data.points_convert?.config?.points||10;f.querySelector('[name=convert_minutes]').value=data.points_convert?.config?.minutes||5;});
const sm=document.getElementById('stationModal');sm.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget,edit=b?.dataset.mode==='edit',f=sm.querySelector('form');f.reset();f.querySelector('[name=action]').value=edit?'update':'create';f.querySelector('[name=id]').value=edit?b.dataset.id:'0';if(edit){f.querySelector('[name=name]').value=b.dataset.name;f.querySelector('[name=router_id]').value=b.dataset.router;f.querySelector('[name=portal_theme_id]').value=b.dataset.theme;f.querySelector('[name=server_ip]').value=b.dataset.serverIp;f.querySelector('[name=client_subnet]').value=b.dataset.subnet;f.querySelector('[name=interface_name]').value=b.dataset.interface;f.querySelector('[name=password_mode]').value=b.dataset.passwordMode;f.querySelector('[name=base_url]').value=b.dataset.url;f.querySelector('[name=charging_enabled]').checked=b.dataset.charging==='1';f.querySelector('[name=eload_enabled]').checked=b.dataset.eload==='1';f.querySelector('[name=enabled]').checked=b.dataset.enabled==='1';}document.getElementById('stationModalTitle').textContent=edit?'Edit hotspot station':'Add hotspot station';document.getElementById('station-submit').textContent=edit?'Save changes':'Add station';});
</script><?php endif;?>
